create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), award_space_id uuid not null references public.award_spaces(id) on delete cascade, recipient text not null, channel text not null, template text not null, status text not null default 'pending', payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), sent_at timestamptz); create index if not exists notifications_space_created_idx on public.notifications(award_space_id,created_at desc); alter table public.notifications enable row level security;
